css:
.print-format { padding: 0 !important; margin: 0 !important; max-width: 80mm; }
.zr { width: 72mm; margin: 0 auto; font-family: monospace, sans-serif; font-size: 12px; color: #000; }
.zr-c { text-align: center; }
.zr-r { text-align: right; white-space: nowrap; }
.zr-b { font-weight: bold; }
.zr-l { font-size: 15px; }
.zr-s { font-size: 10px; }
.zr-hr { border-top: 1px dashed #000; margin: 6px 0; }
.zr-t { width: 100%; border-collapse: collapse; font-size: inherit; }
.zr-t td { padding: 1px 0; vertical-align: top; }
@page { size: 80mm auto; margin: 2mm; }
